function render_catalog(): void {
    $filters = [
        'q' => trim((string)($_GET['q'] ?? '')),
        'category_id' => max(0, (int)($_GET['category_id'] ?? 0)),
        'min_price' => max(0, (int)($_GET['min_price'] ?? 0)),
        'max_price' => max(0, (int)($_GET['max_price'] ?? 0)),
        'min_condition' => max(0, (int)($_GET['min_condition'] ?? 0)),
        'size' => trim((string)($_GET['size'] ?? '')),
        'sort' => (string)($_GET['sort'] ?? 'newest'),
    ];
    $categories = db()->query('SELECT id,name FROM categories WHERE parent_id IS NULL AND is_active=1 ORDER BY sort_order')->fetchAll();
    $basePath = rtrim(str_replace('\\', '/', dirname((string)($_SERVER['SCRIPT_NAME'] ?? '/index.php'))), '/');
    if ($basePath === '.') $basePath = '';
    $apiBase = $basePath . '/api';
    customer_start('Katalog', 'catalog'); ?>
    <main class="page"><div class="crumbs"><a href="<?=h(route_url('home'))?>">Beranda</a><span>/</span><b>Katalog</b></div><div class="page-head"><div><h1 class="h1">KATALOG</h1><p class="lead">Cari barang preloved berdasarkan kategori, ukuran, harga, dan kondisi.</p></div><span class="small muted" data-result-count>Memuat katalog...</span></div>
      <div class="cat-layout" data-catalog-app data-base-url="<?=h($basePath)?>" data-products-url="<?=h($apiBase . '/products')?>" data-session-url="<?=h($apiBase . '/session')?>" data-cart-items-url="<?=h($apiBase . '/cart/items')?>" data-login-url="<?=h($basePath . '/index.php?r=login')?>">
        <aside class="filters"><form class="filters-form" id="catalogFilters" data-catalog-filters method="get"><input type="hidden" name="r" value="catalog">
          <div class="fld"><label for="q">Cari barang</label><input id="q" name="q" value="<?=h($filters['q'])?>" placeholder="Nama, merek, toko"></div>
          <div class="fld"><label for="category_id">Kategori</label><select id="category_id" name="category_id"><option value="0">Semua kategori</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?=$filters['category_id']===(int)$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach; ?></select></div>
          <div class="fld"><label for="min_price">Harga minimum (Rp)</label><input type="number" min="0" id="min_price" name="min_price" value="<?=h($filters['min_price']?:'')?>" placeholder="0"></div>
          <div class="fld"><label for="max_price">Harga maksimum (Rp)</label><input type="number" min="0" id="max_price" name="max_price" value="<?=h($filters['max_price']?:'')?>" placeholder="300000"></div>
          <div class="fld"><label for="min_condition">Kondisi minimum</label><select id="min_condition" name="min_condition"><option value="0">Semua skor</option><?php for($i=6;$i<=10;$i++): ?><option value="<?=$i?>" <?=$filters['min_condition']===$i?'selected':''?>><?=$i?>/10</option><?php endfor; ?></select></div>
          <div class="fld"><label for="size">Ukuran label</label><select id="size" name="size"><option value="">Semua ukuran</option><?php foreach(['XS','S','M','L','XL','XXL','28','30','32','34','36','38','39','40','41','42','43','One size'] as $size): ?><option <?=$filters['size']===$size?'selected':''?> value="<?=h($size)?>"><?=h($size)?></option><?php endforeach; ?></select></div>
          <div class="fld"><label for="sort">Urutkan</label><select id="sort" name="sort"><option value="newest" <?=$filters['sort']==='newest'?'selected':''?>>Terbaru</option><option value="price_low" <?=$filters['sort']==='price_low'?'selected':''?>>Harga terendah</option><option value="price_high" <?=$filters['sort']==='price_high'?'selected':''?>>Harga tertinggi</option><option value="condition" <?=$filters['sort']==='condition'?'selected':''?>>Kondisi terbaik</option></select></div>
          <button class="btn btn--block" type="submit">Terapkan filter</button><a class="btn btn--ghost btn--block" href="<?=h(route_url('catalog'))?>">Reset</a>
        </form></aside>
        <div class="results"><div class="toolbar"><span>Data dimuat langsung dari endpoint API</span><span>Foto dan kondisi sesuai listing</span></div><div class="grid products" data-catalog-grid aria-live="polite" aria-busy="true"><div class="banner-empty">Menghubungkan ke API katalog...</div></div><div data-catalog-pagination hidden></div><p data-catalog-feedback hidden aria-live="polite"></p></div>
      </div>
    </main>
    <script src="assets/catalog-api.js" defer></script>
    <?php customer_end();
}

function render_product(): void {
    $id=max(1,(int)($_GET['id']??1)); $p=product_by_id($id);
    if (!$p) { customer_start('Produk tidak ditemukan'); echo '<main class="page"><div class="banner-empty">Produk tidak ditemukan atau belum tersedia.</div></main>'; customer_end(); return; }
    $photos=product_photos($id); $q=db()->prepare('SELECT d.note,t.name,ph.path AS photo_path FROM product_defects d JOIN defect_tags t ON t.id=d.defect_tag_id LEFT JOIN product_photos ph ON ph.id=d.photo_id WHERE d.product_id=? ORDER BY t.sort_order'); $q->execute([$id]); $defects=$q->fetchAll();
    $m=db()->prepare('SELECT mt.name,mt.unit,pm.value_cm FROM product_measurements pm JOIN measurement_types mt ON mt.id=pm.measurement_type_id WHERE pm.product_id=? ORDER BY mt.id'); $m->execute([$id]); $measurements=$m->fetchAll();
    $same=get_product_cards(4,['shop_id'=>(int)$p['shop_id']]); $u=user(); $isFav=false;
    if ($u) { $f=db()->prepare('SELECT 1 FROM favorites WHERE user_id=? AND product_id=?'); $f->execute([(int)$u['id'],$id]); $isFav=(bool)$f->fetchColumn(); }
    customer_start($p['title']); ?>
    <main class="page"><div class="crumbs"><a href="<?=h(route_url('home'))?>">Beranda</a><span>/</span><a href="<?=h(route_url('catalog'))?>">Katalog</a><span>/</span><b><?=h($p['title'])?></b></div>
      <div class="product-detail"><section><div class="detail-gallery"><?php if($photos): foreach($photos as $i=>$ph): ?><img class="<?=$i===0?'detail-main-img':''?>" src="<?=h(product_photo_url($ph['path']))?>" alt="<?=h($p['title'].' - '.$ph['type'])?>" loading="lazy"><?php endforeach; else: ?><img class="detail-main-img" src="assets/img/hero.jpg" alt="Foto belum tersedia"><?php endif; ?></div></section>
      <section><div class="crumbs"><?=h($p['category_name'])?> · <?=h($p['gender'])?></div><h1 class="h1" style="font-size:clamp(38px,5vw,62px)"><?=h(strtoupper($p['title']))?></h1><div class="row" style="margin-top:12px;gap:8px"><span class="badge" style="position:static"><?= (int)$p['condition_score'] ?>/10</span><?=pill($p['status'])?></div><p class="price-xl"><?=money($p['price'])?></p><p class="lead"><?=h($p['description']?:'Deskripsi belum ditambahkan oleh penjual.')?></p>
        <div class="product-actions"><?php if($p['status']==='active'): ?><form method="post" action="<?=h(route_url('product',['id'=>$id]))?>"><?=csrf_field()?><input type="hidden" name="action" value="add_cart"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="back_route" value="product"><button class="btn btn--block" type="submit">Masukkan keranjang</button></form><form method="post" action="<?=h(route_url('product',['id'=>$id]))?>"><?=csrf_field()?><input type="hidden" name="action" value="add_cart"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="back_route" value="product"><button class="btn btn--sky btn--block" type="submit">Beli sekarang</button></form><?php else: ?><button class="btn btn--block" disabled>Barang tidak tersedia</button><?php endif; ?><form method="post" action="<?=h(route_url('product',['id'=>$id]))?>"><?=csrf_field()?><input type="hidden" name="action" value="toggle_favorite"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="back_route" value="product"><button class="btn btn--ghost btn--block" type="submit"><?=$isFav?'Hapus favorit':'Simpan favorit'?></button></form></div>
        <div class="seller"><span class="ava"><?=h(mb_strtoupper(mb_substr($p['shop_name'],0,1)))?></span><div style="flex:1"><b><?=h($p['shop_name'])?></b><div class="small muted"><?=h($p['shop_city'])?> · <?=h($p['seller_name'])?></div></div><a class="btn btn--ghost btn--sm" href="<?=h(route_url('shop',['id'=>(int)$p['shop_id']]))?>">Lihat toko</a></div>
        <div class="section-line"><h2 class="h3">UKURAN ASLI (CM)</h2><?php if($measurements): ?><div class="kv"><?php foreach($measurements as $mm): ?><span><?=h($mm['name'])?></span><span><?=h($mm['value_cm'])?> <?=h($mm['unit'])?></span><?php endforeach; ?></div><?php else: ?><p class="muted" style="margin-top:10px">Penjual belum mengisi pengukuran rinci.</p><?php endif; ?></div>
        <div class="section-line"><h2 class="h3">FOTO CACAT & CATATAN</h2><?php if($defects): ?><ul class="list-clean"><?php foreach($defects as $d): ?><li><b><?=h($d['name'])?></b><div class="small muted"><?=h($d['note']?:'Tidak ada catatan tambahan.')?></div><?php if($d['photo_path']): ?><img class="thumb-sm" style="margin-top:8px" src="<?=h(product_photo_url($d['photo_path']))?>" alt="Foto cacat <?=h($d['name'])?>"><?php endif; ?></li><?php endforeach; ?></ul><?php else: ?><p class="muted" style="margin-top:10px">Tidak ada cacat yang ditandai oleh penjual.</p><?php endif; ?></div>
        <div class="section-line"><h2 class="h3">DETAIL BARANG</h2><div class="kv"><span>Merek</span><span><?=h($p['brand_name']?:'Tanpa merek')?></span><span>Bahan</span><span><?=h($p['material']?:'—')?></span><span>Warna</span><span><?=h($p['color']?:'—')?></span><span>Ukuran label</span><span><?=h($p['size_label'])?></span><span>Berat</span><span><?=number_format((int)$p['weight_gram'],0,',','.')?> gram</span></div></div>
      </section></div>
      <section class="sec" style="padding-left:0;padding-right:0"><div class="sec__head"><h2>BARANG LAIN DARI TOKO <?=h(strtoupper($p['shop_name']))?></h2><a class="link" href="<?=h(route_url('shop',['id'=>(int)$p['shop_id']]))?>">Lihat toko ↗</a></div><?php product_cards(array_values(array_filter($same,fn($x)=>(int)$x['id']!==$id))); ?></section>
    </main><?php customer_end();
}

function render_shop(): void {
    $shopId=max(1,(int)($_GET['id']??1)); $q=db()->prepare('SELECT s.*,u.name FROM shops s JOIN users u ON u.id=s.user_id WHERE s.id=? AND s.is_active=1'); $q->execute([$shopId]); $shop=$q->fetch();
    customer_start($shop['name']??'Toko');
    if (!$shop) { echo '<main class="page"><div class="banner-empty">Toko tidak ditemukan.</div></main>'; customer_end(); return; }
    $stats=db()->prepare('SELECT * FROM v_shop_stats WHERE shop_id=?'); $stats->execute([$shopId]); $st=$stats->fetch()?:[];
    $reviews=db()->prepare('SELECT r.*,u.name AS buyer_name FROM reviews r JOIN users u ON u.id=r.buyer_id WHERE r.shop_id=? ORDER BY r.created_at DESC LIMIT 8'); $reviews->execute([$shopId]);
    $products=get_product_cards(60,['shop_id'=>$shopId]); ?>
    <main class="page"><div class="crumbs"><a href="<?=h(route_url('home'))?>">Beranda</a><span>/</span><b>Toko</b></div><div class="seller" style="padding:24px;margin-bottom:24px"><span class="ava" style="width:64px;height:64px;font-size:26px"><?=h(mb_strtoupper(mb_substr($shop['name'],0,1)))?></span><div style="flex:1"><h1 class="h1" style="font-size:48px"><?=h(strtoupper($shop['name']))?></h1><p class="lead"><?=h($shop['description']?:'Toko preloved di ThriftApp.')?></p><div class="small muted" style="margin-top:8px"><?=h($shop['city'])?> · <?=h($st['rating_avg']??$shop['rating_avg'])?>/5 · <?=h($st['review_count']??$shop['review_count'])?> ulasan · <?=h($st['sold_count']??$shop['sold_count'])?> terjual</div></div></div>
      <div class="sec" style="padding:0"><div class="sec__head"><h2>BARANG TOKO</h2><span class="muted small"><?=count($products)?> barang</span></div><?php product_cards($products); ?></div>
      <section class="section-line"><h2 class="h2">ULASAN TERBARU</h2><?php $rws=$reviews->fetchAll(); if(!$rws) echo '<div class="banner-empty" style="margin-top:14px">Belum ada ulasan dari pembeli.</div>'; else foreach($rws as $r): ?><div class="section-line"><b><?=h($r['buyer_name'])?></b> · <span class="pill pill--sky"><?= (int)$r['rating'] ?>/5</span><p style="margin-top:6px"><?=h($r['comment']?:'Pembeli tidak menambahkan komentar.')?></p><small class="muted"><?=h(dt($r['created_at']))?></small></div><?php endforeach; ?></section>
    </main><?php customer_end();
}

