function render_account(): void {
    $u=require_login(); $pdo=db();
    $aq=$pdo->prepare('SELECT * FROM addresses WHERE user_id=? ORDER BY is_default DESC,id'); $aq->execute([(int)$u['id']]); $addresses=$aq->fetchAll();
    $editId=(int)($_GET['edit_address']??0); $edit=null; foreach($addresses as $a) if((int)$a['id']===$editId) $edit=$a;
    $countOrders=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE buyer_id=?'); $countOrders->execute([(int)$u['id']]); $orderCount=(int)$countOrders->fetchColumn();
    $fav=$pdo->prepare('SELECT COUNT(*) FROM favorites WHERE user_id=?'); $fav->execute([(int)$u['id']]); $favCount=(int)$fav->fetchColumn();
    $cart=$pdo->prepare('SELECT COUNT(*) FROM cart_items WHERE user_id=?'); $cart->execute([(int)$u['id']]); $cartCount=(int)$cart->fetchColumn();
    $nq=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 5'); $nq->execute([(int)$u['id']]); $notifs=$nq->fetchAll();
    customer_start('Akun'); ?>
