      <div class="metric-grid"><a class="metric" href="<?=h(route_url('orders'))?>"><span>PESANAN</span><b><?=$orderCount?></b><span>Lihat riwayat</span></a><a class="metric" href="<?=h(route_url('favorites'))?>"><span>FAVORIT</span><b><?=$favCount?></b><span>Barang incaran</span></a><a class="metric" href="<?=h(route_url('cart'))?>"><span>KERANJANG</span><b><?=$cartCount?></b><span>Barang disimpan</span></a><a class="metric" href="<?=h(route_url('seller_dashboard'))?>"><span>MODE PENJUAL</span><b><?=$u['is_seller']?'AKTIF':'—'?></b><span>Kelola toko ↗</span></a></div>
