function render_cart(): void {
    $u=require_login(); $q=db()->prepare("SELECT ci.id AS cart_item_id,p.*,s.name AS shop_name,s.city AS shop_city,(SELECT path FROM product_photos ph WHERE ph.product_id=p.id ORDER BY ph.sort_order,ph.id LIMIT 1) main_photo FROM cart_items ci JOIN products p ON p.id=ci.product_id JOIN shops s ON s.id=p.shop_id WHERE ci.user_id=? ORDER BY s.name,p.created_at DESC"); $q->execute([(int)$u['id']]); $items=$q->fetchAll(); $valid=array_filter($items,fn($p)=>$p['status']==='active'); $total=array_sum(array_map(fn($p)=>(int)$p['price'],$valid));
    customer_start('Keranjang'); ?>
