      <p data-cart-feedback hidden aria-live="polite"></p><div class="two"><section class="panel"><div class="panel__h"><h3>Daftar barang</h3></div><div class="panel__b"><?php if(!$items): ?><div class="banner-empty">Keranjang masih kosong. Temukan barang preloved yang kamu suka.</div><a class="btn" style="margin-top:14px" href="<?=h(route_url('catalog'))?>">Jelajahi katalog</a><?php else: foreach($items as $p): ?><div class="product-row"><a href="<?=h(route_url('product',['id'=>$p['id']]))?>"><img src="<?=h(product_card_image($p))?>" alt="<?=h($p['title'])?>"></a><div><b><?=h($p['title'])?></b><p class="small muted"><?=h($p['shop_name'])?> · ukuran <?=h($p['size_label'])?></p><p style="margin-top:5px"><?=money($p['price'])?></p><div style="margin-top:5px"><?=pill($p['status'])?></div></div><form method="post" data-cart-delete-form data-cart-item-id="<?= (int)$p['cart_item_id'] ?>"><?=csrf_field()?><input type="hidden" name="action" value="remove_cart"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="hidden" name="back_route" value="cart"><button type="submit" class="btn btn--ghost btn--sm">Hapus</button></form></div><?php endforeach; endif; ?></div></section>
      <aside class="panel"><div class="panel__h"><h3>Ringkasan belanja</h3></div><div class="panel__b"><div class="sum"><span>Subtotal barang aktif</span><b><?=money($total)?></b></div><div class="sum"><span>Ongkir</span><span>Dihitung saat checkout</span></div><div class="sum"><span>Biaya layanan</span><span><?=money((int)setting('service_fee','3000'))?></span></div><div class="sum sum--total"><span>Subtotal</span><b><?=money($total)?></b></div><?php if($valid): ?><a class="btn btn--block" style="margin-top:16px" href="<?=h(route_url('checkout'))?>">Lanjut ke checkout</a><?php else: ?><button class="btn btn--block" disabled>Barang aktif tidak tersedia</button><?php endif; ?><a class="btn btn--ghost btn--block" style="margin-top:8px" href="<?=h(route_url('catalog'))?>">Lanjut belanja</a><p class="small muted" style="margin-top:14px">Checkout menahan barang selama 30 menit. Pembayaran di proyek ini hanya simulasi sandbox.</p></div></aside></div>
    </main><script src="assets/cart-api.js" defer></script><?php customer_end();
}

