function render_checkout(): void {
    $u=require_login(); $pdo=db();
    $q=$pdo->prepare("SELECT p.*,s.name AS shop_name,s.city AS shop_city,(SELECT path FROM product_photos ph WHERE ph.product_id=p.id ORDER BY ph.sort_order,ph.id LIMIT 1) main_photo FROM cart_items ci JOIN products p ON p.id=ci.product_id JOIN shops s ON s.id=p.shop_id WHERE ci.user_id=? AND p.status='active' ORDER BY s.name"); $q->execute([(int)$u['id']]); $items=$q->fetchAll();
    $aq=$pdo->prepare('SELECT * FROM addresses WHERE user_id=? ORDER BY is_default DESC,id'); $aq->execute([(int)$u['id']]); $addresses=$aq->fetchAll();
    $couriers=$pdo->query('SELECT * FROM couriers WHERE is_active=1 ORDER BY id')->fetchAll(); $methods=$pdo->query('SELECT * FROM payment_methods WHERE is_active=1 ORDER BY sort_order')->fetchAll();
    $itemsTotal=array_sum(array_map(fn($p)=>(int)$p['price'],$items)); $shopCount=count(array_unique(array_map(fn($p)=>(int)$p['shop_id'],$items))); $shipping=18000*$shopCount; $fee=(int)setting('service_fee','3000');
    customer_start('Checkout'); ?>
    <main class="page"><div class="page-head"><div><div class="crumbs"><a href="<?=h(route_url('cart'))?>">Keranjang</a><span>/</span><b>Checkout</b></div><h1 class="h1">CHECKOUT</h1><p class="lead">Periksa alamat dan ringkasan sebelum pembayaran dimulai.</p></div></div>
      <?php if(!$items): ?><div class="banner-empty">Tidak ada barang aktif untuk checkout. Kembali ke katalog atau keranjang.</div><a class="btn" style="margin-top:14px" href="<?=h(route_url('cart'))?>">Kembali ke keranjang</a><?php elseif(!$addresses): ?><div class="notice notice--warn"><div>Tambahkan alamat pengiriman terlebih dahulu dari halaman akun.</div></div><a class="btn" style="margin-top:14px" href="<?=h(route_url('account'))?>">Tambah alamat</a><?php else: ?>
      <form method="post" class="two"><?=csrf_field()?><input type="hidden" name="action" value="checkout_create"><input type="hidden" name="back_route" value="checkout"><section><div class="panel"><div class="panel__h"><h3>Alamat pengiriman</h3><a class="small footer-link" href="<?=h(route_url('account'))?>">Kelola alamat</a></div><div class="panel__b stack-form"><?php foreach($addresses as $a): ?><label class="seller" style="align-items:flex-start;cursor:pointer"><input type="radio" name="address_id" value="<?=$a['id']?>" <?=$a['is_default']?'checked':''?> required><div><b><?=h($a['label'])?> <?=$a['is_default']?'· Alamat utama':''?></b><p><?=h($a['recipient_name'])?> · <?=h($a['phone'])?></p><p class="small muted"><?=h($a['street'])?>, <?=h($a['city'])?>, <?=h($a['province'])?> <?=h($a['postal_code'])?></p></div></label><?php endforeach; ?></div></div>
      <div class="panel" style="margin-top:18px"><div class="panel__h"><h3>Kurir dan pembayaran</h3></div><div class="panel__b form form--2"><label class="fld">Kurir untuk setiap toko<select name="courier_id"><?php foreach($couriers as $c): ?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach; ?></select><small class="muted">Tarif demo Rp18.000 per toko.</small></label><label class="fld">Metode pembayaran<select name="payment_method_id"><?php foreach($methods as $m): ?><option value="<?=$m['id']?>"><?=h($m['name'])?></option><?php endforeach; ?></select><small class="muted">Pembayaran masih berupa simulasi sandbox.</small></label></div></div>
      <div class="panel" style="margin-top:18px"><div class="panel__h"><h3>Barang yang dibeli</h3></div><div class="panel__b"><?php foreach($items as $p): ?><div class="product-row"><img src="<?=h(product_card_image($p))?>" alt="<?=h($p['title'])?>"><div><b><?=h($p['title'])?></b><p class="small muted"><?=h($p['shop_name'])?> · ukuran <?=h($p['size_label'])?></p></div><b><?=money($p['price'])?></b></div><?php endforeach; ?></div></div></section>
      <aside class="panel"><div class="panel__h"><h3>Ringkasan pembayaran</h3></div><div class="panel__b"><div class="sum"><span>Subtotal barang</span><b><?=money($itemsTotal)?></b></div><div class="sum"><span>Ongkir (<?=$shopCount?> toko)</span><b><?=money($shipping)?></b></div><div class="sum"><span>Biaya layanan</span><b><?=money($fee)?></b></div><div class="sum sum--total"><span>Total bayar</span><b><?=money($itemsTotal+$shipping+$fee)?></b></div><div class="notice notice--sky" style="margin:14px 0"><div>Setelah checkout, barang ditahan selama 30 menit. Pembayaran yang berhasil akan masuk ke status dana ditahan.</div></div><button class="btn btn--block" type="submit">Buat pesanan & lanjut bayar</button><a class="btn btn--ghost btn--block" style="margin-top:8px" href="<?=h(route_url('cart'))?>">Kembali</a></div></aside></form><?php endif; ?>
    </main><?php customer_end();
