function render_payment(): void {
    $u=require_login(); $id=max(1,(int)($_GET['id']??0)); $q=db()->prepare('SELECT c.*,p.id AS payment_id,p.status AS payment_status,p.va_number,p.gateway_ref,p.expires_at,m.name AS method_name FROM checkouts c JOIN payments p ON p.checkout_id=c.id JOIN payment_methods m ON m.id=p.payment_method_id WHERE c.id=? AND c.buyer_id=?'); $q->execute([$id,(int)$u['id']]); $co=$q->fetch();
    customer_start('Pembayaran'); if(!$co){echo '<main class="page"><div class="banner-empty">Checkout tidak ditemukan.</div></main>';customer_end();return;}
    $oq=db()->prepare('SELECT * FROM orders WHERE checkout_id=? ORDER BY id');$oq->execute([$id]);$orders=$oq->fetchAll(); ?>
    <main class="page"><div class="crumbs"><a href="<?=h(route_url('checkout'))?>">Checkout</a><span>/</span><b>Pembayaran</b></div><h1 class="h1">BAYAR</h1><p class="lead">Nomor checkout #<?=h($co['id'])?> · Batas bayar <?=h(dt($co['payment_expires_at']))?></p><div class="two" style="margin-top:24px"><section class="panel"><div class="panel__h"><h3>Instruksi pembayaran sandbox</h3><?=pill($co['status'])?></div><div class="panel__b"><p>Metode: <b><?=h($co['method_name'])?></b></p><div class="notice notice--sky" style="margin:14px 0"><div><small>Nomor pembayaran virtual demo</small><h2 class="h2" style="margin:8px 0"><?=h($co['va_number'])?></h2><p class="small muted">Referensi: <?=h($co['gateway_ref'])?></p></div></div><div class="sum sum--total"><span>Total pembayaran</span><b><?=money($co['grand_total'])?></b></div><p class="small muted" style="margin:12px 0">Ini simulasi pembayaran; tidak ada transaksi uang sungguhan. Tekan tombol di bawah untuk menandai pembayaran berhasil.</p><?php if($co['status']==='awaiting_payment' && strtotime($co['payment_expires_at'])>=time()): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="pay_sandbox"><input type="hidden" name="checkout_id" value="<?=$id?>"><input type="hidden" name="back_route" value="payment"><button class="btn btn--block" type="submit">Saya sudah bayar (simulasi)</button></form><?php elseif($co['status']==='paid'): ?><a class="btn btn--block" href="<?=h(route_url('success',['id'=>$id]))?>">Lihat pesanan</a><?php else: ?><div class="notice notice--warn">Batas waktu pembayaran telah berakhir. Silakan checkout ulang.</div><a class="btn" href="<?=h(route_url('cart'))?>">Kembali ke keranjang</a><?php endif; ?></div></section><aside class="panel"><div class="panel__h"><h3>Pesanan per toko</h3></div><div class="panel__b"><?php foreach($orders as $o): ?><div class="section-line" style="padding-top:0"><b><?=h($o['order_number'])?></b><div class="small muted"><?=h($o['courier_name'])?></div><div class="row between" style="margin-top:6px"><span><?=pill($o['status'])?></span><b><?=money($o['total'])?></b></div></div><?php endforeach; ?></div></aside></div></main><?php customer_end();
}
