    $reviewq=db()->prepare('SELECT id FROM reviews WHERE order_id=?');$reviewq->execute([$id]);$hasReview=(bool)$reviewq->fetchColumn(); ?>
    <main class="page"><div class="crumbs"><a href="<?=h(route_url('orders'))?>">Pesanan saya</a><span>/</span><b><?=h($o['order_number'])?></b></div><div class="page-head"><div><h1 class="h1">PESANAN #<?=h($o['order_number'])?></h1><p class="lead">Dibuat <?=h(dt($o['created_at']))?></p></div><?=pill($o['status'])?></div>
      <div class="two"><section><div class="panel"><div class="panel__h"><h3>Barang dipesan</h3></div><div class="panel__b"><?php foreach($items as $it): ?><div class="product-row"><img src="<?=h(product_photo_url($it['photo']))?>" alt="<?=h($it['title_snapshot'])?>"><div><b><?=h($it['title_snapshot'])?></b><p class="small muted">Ukuran <?=h($it['size_snapshot'])?> · Kondisi <?=h($it['condition_snapshot'])?>/10</p><p><?=money($it['price_snapshot'])?></p></div><a class="small footer-link" href="<?=h(route_url('product',['id'=>$it['product_id']]))?>">Lihat barang</a></div><?php endforeach; ?><div class="sum"><span>Subtotal barang</span><b><?=money($o['items_total'])?></b></div><div class="sum"><span>Ongkir</span><b><?=money($o['shipping_cost'])?></b></div><div class="sum sum--total"><span>Total pesanan</span><b><?=money($o['total'])?></b></div></div></div>
      <div class="panel" style="margin-top:18px"><div class="panel__h"><h3>Pengiriman</h3></div><div class="panel__b"><div class="kv"><span>Kurir</span><span><?=h($o['courier_name'])?></span><span>Nomor resi</span><span><?=h($o['tracking_number']?:'Belum tersedia')?></span><span>Estimasi tiba</span><span><?=h($o['estimated_arrival_date']?:'Belum tersedia')?></span><span>Alamat</span><span><?=h($o['address_text'])?></span></div></div></div>
      <div class="panel" style="margin-top:18px"><div class="panel__h"><h3>Riwayat status</h3></div><div class="panel__b"><div class="timeline"><?php foreach($logs as $log): ?><div class="timeline-item"><b><?=h(status_label($log['status']))?></b><p><?=h($log['note']?:'Status pesanan diperbarui.')?></p><small><?=h(dt($log['created_at']))?></small></div><?php endforeach; ?></div></div></div></section>
      <aside><div class="panel"><div class="panel__h"><h3>Tindakan pesanan</h3></div><div class="panel__b stack-form"><?php if($o['status']==='awaiting_payment'): ?><a class="btn btn--block" href="<?=h(route_url('payment',['id'=>(int)$o['checkout_id']]))?>">Bayar sekarang</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="cancel_order"><input type="hidden" name="order_id" value="<?=$id?>"><input type="hidden" name="back_route" value="order"><button type="submit" class="btn btn--danger btn--block">Batalkan pesanan</button></form><?php elseif($o['status']==='shipped'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="mark_delivered"><input type="hidden" name="order_id" value="<?=$id?>"><input type="hidden" name="back_route" value="order"><button class="btn btn--block" type="submit">Barang sudah diterima</button></form><p class="small muted">Setelah konfirmasi, kamu memiliki waktu 2x24 jam untuk memeriksa barang atau mengajukan komplain.</p><?php elseif($o['status']==='delivered' && !$complaint): ?><a class="btn btn--block" href="<?=h(route_url('complaint',['id'=>$id]))?>">Ajukan komplain</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="complete_order"><input type="hidden" name="order_id" value="<?=$id?>"><input type="hidden" name="back_route" value="order"><button class="btn btn--ghost btn--block" type="submit">Selesaikan & teruskan dana</button></form><p class="small muted">Menyelesaikan pesanan akan meneruskan dana ke penjual dan menutup kesempatan komplain.</p><?php elseif($complaint): ?><div class="notice notice--warn"><div><b>Komplain: <?=h(status_label($complaint['status']))?></b><p><?=h($complaint['description'])?></p><a class="footer-link" href="<?=h(route_url('complaint',['id'=>$id]))?>">Lihat detail komplain</a></div></div><?php elseif($o['status']==='completed' && !$hasReview): ?><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="submit_review"><input type="hidden" name="order_id" value="<?=$id?>"><input type="hidden" name="back_route" value="order"><label class="fld">Rating<select name="rating"><?php for($i=5;$i>=1;$i--): ?><option value="<?=$i?>"><?=$i?>/5</option><?php endfor; ?></select></label><label class="fld">Komentar<textarea name="comment" placeholder="Bagaimana pengalaman belanjamu?"></textarea></label><button class="btn btn--block" type="submit">Beri ulasan</button></form><?php elseif($hasReview): ?><p class="muted">Kamu sudah memberi ulasan untuk pesanan ini.</p><?php else: ?><p class="muted">Tidak ada tindakan yang perlu dilakukan untuk status ini.</p><?php endif; ?></div></div>
      <div class="panel" style="margin-top:18px"><div class="panel__h"><h3>Ringkasan dana</h3></div><div class="panel__b"><div class="sum"><span>Komisi platform (5%)</span><span><?=money($o['commission'])?></span></div><div class="sum"><span>Diterima penjual sebelum komplain</span><b><?=money($o['seller_net'])?></b></div><p class="small muted" style="margin-top:10px">Dana ditahan sampai pesanan selesai. Pembayaran dan refund di versi ini adalah simulasi sandbox.</p></div></div></aside></div></main><?php customer_end();
}

function render_complaint(): void {
    $u=require_login(); $orderId=max(1,(int)($_GET['id']??0)); $o=own_order($orderId,(int)$u['id'],'buyer');customer_start('Ajukan komplain');
    if(!$o){echo '<main class="page"><div class="banner-empty">Pesanan tidak ditemukan.</div></main>';customer_end();return;}
    $cq=db()->prepare('SELECT * FROM complaints WHERE order_id=?');$cq->execute([$orderId]);$c=$cq->fetch();
    $itemsQ=db()->prepare('SELECT id,title_snapshot FROM order_items WHERE order_id=?');$itemsQ->execute([$orderId]);$items=$itemsQ->fetchAll();
    if($c){$eq=db()->prepare('SELECT ce.*,u.name FROM complaint_evidence ce JOIN users u ON u.id=ce.uploaded_by WHERE complaint_id=? ORDER BY ce.created_at');$eq->execute([(int)$c['id']]);$ev=$eq->fetchAll();} else $ev=[]; ?>
    <main class="page"><div class="crumbs"><a href="<?=h(route_url('order',['id'=>$orderId]))?>">Detail pesanan</a><span>/</span><b>Komplain</b></div><h1 class="h1">AJUKAN KOMPLAIN</h1><p class="lead">Gunakan alasan yang sesuai dan tambahkan foto bukti. Batas normal pengajuan adalah 2x24 jam setelah barang diterima.</p><div class="two" style="margin-top:22px"><section class="panel"><div class="panel__h"><h3>Pesanan <?=h($o['order_number'])?></h3><?=pill($o['status'])?></div><div class="panel__b"><?php if($c): ?><h2 class="h2">KOMPLAIN <?=h(strtoupper(status_label($c['status'])))?></h2><div class="kv"><span>Alasan</span><span><?=h(status_label($c['reason']))?></span><span>Deskripsi</span><span><?=h($c['description'])?></span><span>Sikap penjual</span><span><?=h($c['seller_stance']?status_label($c['seller_stance']):'Belum merespons')?></span><span>Tanggapan</span><span><?=h($c['seller_response']?:'Belum ada tanggapan')?></span><span>Keputusan</span><span><?=h(status_label($c['decision']))?></span><span>Catatan admin</span><span><?=h($c['decision_note']?:'Belum ada keputusan')?></span></div><h3 class="h3" style="margin-top:18px">BUKTI</h3><div class="gal" style="margin-top:12px"><?php foreach($ev as $e): ?><div><img src="<?=h(product_photo_url($e['path']))?>" alt="Bukti komplain"><span><?=h($e['caption']?:$e['side'])?></span></div><?php endforeach; ?></div><?php if(!$ev): ?><p class="muted">Belum ada foto bukti.</p><?php endif; ?><?php else: ?>
      <?php if($o['status']!=='delivered' || ($o['complaint_deadline_at'] && strtotime($o['complaint_deadline_at'])<time())): ?><div class="notice notice--warn">Komplain hanya dapat diajukan setelah barang berstatus diterima dan sebelum batas waktunya berakhir.</div><?php else: ?><form method="post" enctype="multipart/form-data" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="submit_complaint"><input type="hidden" name="order_id" value="<?=$orderId?>"><input type="hidden" name="back_route" value="complaint"><label class="fld">Barang yang dikomplain<select name="order_item_id"><option value="0">Seluruh pesanan</option><?php foreach($items as $it): ?><option value="<?=$it['id']?>"><?=h($it['title_snapshot'])?></option><?php endforeach; ?></select></label><label class="fld">Alasan komplain<select name="reason" required><option value="">Pilih alasan</option><option value="undisclosed_defect">Cacat tidak disebutkan</option><option value="size_mismatch">Ukuran tidak sesuai</option><option value="color_mismatch">Warna berbeda</option><option value="wrong_item">Barang salah</option><option value="damaged_in_shipping">Rusak saat pengiriman</option><option value="not_arrived">Barang belum tiba</option><option value="other">Lainnya</option></select></label><label class="fld">Jelaskan masalah<textarea name="description" minlength="10" required placeholder="Ceritakan perbedaan barang dengan listing..."></textarea></label><label class="fld">Foto bukti (JPG/PNG/WEBP, maks. 5 MB per foto)<input type="file" name="evidence[]" accept="image/jpeg,image/png,image/webp" multiple></label><button class="btn btn--block" type="submit">Kirim komplain</button></form><?php endif; ?><?php endif; ?></div></section>
      <aside class="panel"><div class="panel__h"><h3>Aturan komplain</h3></div><div class="panel__b"><ul class="list-clean"><li>Ajukan dalam waktu 2x24 jam setelah menerima barang.</li><li>Gunakan alasan yang paling sesuai dan jelaskan dengan jelas.</li><li>Foto bukti membantu penjual dan admin memeriksa masalah.</li><li>Penjual diberi waktu 2x24 jam untuk menjawab.</li><li>Admin memutuskan refund penuh, sebagian, atau menolak komplain.</li></ul><a class="btn btn--ghost btn--block" style="margin-top:14px" href="<?=h(route_url('order',['id'=>$orderId]))?>">Kembali ke detail pesanan</a></div></aside></div></main><?php customer_end();
}
